function bigger(rock, fire) {
  return Math.max(rock, fire);
}

function total(tribe) {
  let sun = 0;
  for (const stick of tribe) {
    sun = (sun + stick);
  }
  return sun;
}

function countBig(tribe) {
  let mammoth = 0;
  for (const hunt of tribe) {
    if ((hunt > 10)) {
      mammoth = (mammoth + 1);
    }
  }
  return mammoth;
}

function factorial(rock) {
  let bear = 1;
  for (let stick = 1; stick < rock; stick++) {
    bear = (bear * stick);
  }
  return bear;
}

function clamp(rock, low, high) {
  if ((rock < low)) {
    return low;
  } else {
    if ((rock > high)) {
      return high;
    }
    return rock;
  }
}

function sign(rock) {
  if ((rock > 0)) {
    return 1;
  } else {
    if ((rock < 0)) {
      return -1;
    } else {
      return 0;
    }
  }
}

function reverseWord(word) {
  return word.split("");
  return word.reverse();
}
